def flatten(d: dict) -> dict:
    flattened = {}
    for key, value in d.items():
        if isinstance(value, dict):
            flattened[f"{key}.{k}"] = v for k, v in value.items()
        else:
            flattened[key] = value
    return {k: v for k, v in flattened.items() if not (isinstance(v, dict))}
```

