import re

def parse_money(s: str) -> float | None:
    if not s.strip():
        return None

    # Remove dollar sign, commas, and convert to float
    cleaned = re.sub(r'[^\d.]', '', s)
    try:
        return float(cleaned)
    except ValueError:
        return None
```

